query ShopInfo {
  shop {
    countries {
      ...CountryWithCode
    }
    defaultCountry {
      ...CountryWithCode
    }
    defaultWeightUnit
    domain {
      host
      url
    }
    languages {
      ...Language
    }
    name
    permissions {
      ...Permission
    }
    version
  }
}

fragment CountryWithCode on CountryDisplay {
  country
  code
}

fragment Language on LanguageDisplay {
  code
  language
}

fragment Permission on Permission {
  code
  name
}
